from __future__ import annotations

import io
import json
import os
import re
import sqlite3
import threading
from datetime import datetime, timezone
from pathlib import Path

import cv2
import numpy as np
from flask import Flask, jsonify, render_template, request
from werkzeug.exceptions import RequestEntityTooLarge
from werkzeug.utils import secure_filename

try:
    import face_recognition
    FACE_RECOGNITION_ERROR = None
except ImportError as exc:  # Keep the dashboard usable while setup is incomplete.
    face_recognition = None
    FACE_RECOGNITION_ERROR = str(exc)

BASE_DIR = Path(__file__).resolve().parent
DATA_DIR = BASE_DIR / "data"
SAMPLE_DIR = DATA_DIR / "face_samples"
DB_PATH = DATA_DIR / "attendance.db"
KNOWN_DIR = BASE_DIR / "know_faces"
ALLOWED_EXTENSIONS = {"jpg", "jpeg", "png", "webp"}
MAX_UPLOAD_BYTES = 8 * 1024 * 1024
MATCH_THRESHOLD = float(os.getenv("FACE_MATCH_THRESHOLD", "0.48"))
COOLDOWN_SECONDS = int(os.getenv("ATTENDANCE_COOLDOWN_SECONDS", "3600"))
RECOGNITION_SCALE = float(os.getenv("RECOGNITION_SCALE", "0.5"))
DB_LOCK = threading.RLock()

app = Flask(__name__, template_folder="templates", static_folder="static")
app.config["MAX_CONTENT_LENGTH"] = MAX_UPLOAD_BYTES


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def db() -> sqlite3.Connection:
    DATA_DIR.mkdir(exist_ok=True)
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def init_db() -> None:
    with db() as conn:
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS people (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            person_id TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            department TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS face_samples (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE CASCADE,
            filename TEXT NOT NULL,
            embedding TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS attendance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            person_id INTEGER NOT NULL REFERENCES people(id) ON DELETE CASCADE,
            attendance_date TEXT NOT NULL,
            marked_at TEXT NOT NULL,
            confidence REAL NOT NULL,
            status TEXT NOT NULL DEFAULT 'present',
            source TEXT NOT NULL DEFAULT 'camera'
        );
        CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(attendance_date);
        CREATE INDEX IF NOT EXISTS idx_samples_person ON face_samples(person_id);
        """)


def json_row(row: sqlite3.Row) -> dict:
    return dict(row)


def image_from_bytes(raw: bytes):
    image = cv2.imdecode(np.frombuffer(raw, dtype=np.uint8), cv2.IMREAD_COLOR)
    if image is None or image.size == 0:
        raise ValueError("The uploaded file is not a valid image.")
    return image


def encode_sample(image: np.ndarray) -> list[float]:
    if face_recognition is None:
        raise RuntimeError("face-recognition is not installed. See the setup instructions.")
    rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
    locations = face_recognition.face_locations(rgb, model="hog")
    if len(locations) != 1:
        raise ValueError(f"Each sample must contain exactly one face; found {len(locations)}.")
    encodings = face_recognition.face_encodings(rgb, locations)
    if not encodings:
        raise ValueError("A face was detected but could not be encoded.")
    return encodings[0].tolist()


def load_embeddings() -> list[tuple[sqlite3.Row, np.ndarray]]:
    with db() as conn:
        rows = conn.execute("""SELECT p.id, p.person_id, p.name, fs.embedding
                              FROM people p JOIN face_samples fs ON fs.person_id = p.id""").fetchall()
    return [(row, np.asarray(json.loads(row["embedding"]), dtype=np.float64)) for row in rows]


def recognize(image: np.ndarray) -> list[dict]:
    if face_recognition is None:
        raise RuntimeError("face-recognition is not installed. See the setup instructions.")
    small = cv2.resize(image, (0, 0), fx=RECOGNITION_SCALE, fy=RECOGNITION_SCALE)
    rgb = cv2.cvtColor(small, cv2.COLOR_BGR2RGB)
    locations = face_recognition.face_locations(rgb, model="hog")
    encodings = face_recognition.face_encodings(rgb, locations)
    known = load_embeddings()
    output = []
    for encoding, location in zip(encodings, locations):
        best = None
        if known:
            distances = face_recognition.face_distance([e for _, e in known], encoding)
            index = int(np.argmin(distances))
            distance = float(distances[index])
            if distance <= MATCH_THRESHOLD:
                row = known[index][0]
                best = {"person_db_id": row["id"], "person_id": row["person_id"],
                        "name": row["name"], "distance": distance,
                        "confidence": round(max(0.0, 1.0 - distance), 4)}
        top, right, bottom, left = [int(v / RECOGNITION_SCALE) for v in location]
        output.append({"box": {"top": top, "right": right, "bottom": bottom, "left": left},
                       "recognized": best is not None, "match": best})
    return output


def maybe_mark(person_db_id: int, confidence: float, source: str) -> bool:
    current = datetime.now(timezone.utc)
    with DB_LOCK, db() as conn:
        latest = conn.execute("SELECT marked_at FROM attendance WHERE person_id=? ORDER BY id DESC LIMIT 1",
                              (person_db_id,)).fetchone()
        if latest:
            age = (current - datetime.fromisoformat(latest["marked_at"])).total_seconds()
            if age < COOLDOWN_SECONDS:
                return False
        conn.execute("""INSERT INTO attendance
            (person_id, attendance_date, marked_at, confidence, source)
            VALUES (?, ?, ?, ?, ?)""", (person_db_id, current.date().isoformat(), current.isoformat(timespec="seconds"),
                                        confidence, source[:80]))
    return True


def seed_existing_faces() -> None:
    if not KNOWN_DIR.exists() or not face_recognition:
        return
    with db() as conn:
        if conn.execute("SELECT 1 FROM people LIMIT 1").fetchone():
            return
    for image_path in sorted(KNOWN_DIR.iterdir()):
        if image_path.suffix.lower().lstrip(".") not in ALLOWED_EXTENSIONS:
            continue
        try:
            image = cv2.imread(str(image_path))
            embedding = encode_sample(image)
            name = image_path.stem.replace("_", " ").replace("-", " ").title()
            person_id = re.sub(r"[^a-z0-9]+", "-", image_path.stem.lower()).strip("-") or "person"
            with db() as conn:
                stamp = now_iso()
                cur = conn.execute("INSERT INTO people(person_id,name,created_at,updated_at) VALUES(?,?,?,?)",
                                   (person_id, name, stamp, stamp))
                conn.execute("INSERT INTO face_samples(person_id,filename,embedding,created_at) VALUES(?,?,?,?)",
                             (cur.lastrowid, image_path.name, json.dumps(embedding), stamp))
        except (ValueError, cv2.error, sqlite3.IntegrityError):
            continue


@app.errorhandler(RequestEntityTooLarge)
def too_large(_):
    return jsonify(error="Image is too large. Maximum size is 8 MB."), 413


@app.route("/")
def index():
    return render_template("index.html")


@app.get("/api/dashboard")
def dashboard():
    with db() as conn:
        people = conn.execute("SELECT COUNT(*) AS n FROM people").fetchone()["n"]
        today = conn.execute("SELECT COUNT(*) AS n FROM attendance WHERE attendance_date=?",
                             (datetime.now(timezone.utc).date().isoformat(),)).fetchone()["n"]
        recent = conn.execute("""SELECT a.id,p.person_id,p.name,a.marked_at,a.confidence,a.status,a.source
             FROM attendance a JOIN people p ON p.id=a.person_id ORDER BY a.id DESC LIMIT 10""").fetchall()
    return jsonify({"registered_people": people, "today_attendance": today,
                    "recent": [json_row(row) for row in recent], "threshold": MATCH_THRESHOLD,
                    "cooldown_seconds": COOLDOWN_SECONDS, "recognition_available": face_recognition is not None})


@app.get("/api/people")
def people():
    with db() as conn:
        rows = conn.execute("""SELECT p.*, COUNT(fs.id) AS sample_count
            FROM people p LEFT JOIN face_samples fs ON fs.person_id=p.id
            GROUP BY p.id ORDER BY p.name""").fetchall()
    return jsonify([json_row(row) for row in rows])


def valid_text(value: str, label: str) -> str:
    value = (value or "").strip()
    if not value or len(value) > 100:
        raise ValueError(f"{label} is required and must be at most 100 characters.")
    return value


@app.post("/api/people")
def add_person():
    try:
        name = valid_text(request.form.get("name"), "Name")
        person_id = valid_text(request.form.get("person_id"), "ID/roll number")
        department = (request.form.get("department") or "").strip()[:100]
        files = request.files.getlist("images")
        if not files or all(not f.filename for f in files):
            raise ValueError("Add at least one face sample.")
        encoded = []
        for file in files:
            if not file.filename or Path(file.filename).suffix.lower().lstrip(".") not in ALLOWED_EXTENSIONS:
                raise ValueError("Only JPG, JPEG, PNG, and WEBP images are allowed.")
            raw = file.read()
            encoded.append((secure_filename(file.filename), encode_sample(image_from_bytes(raw))))
        with DB_LOCK, db() as conn:
            stamp = now_iso()
            cur = conn.execute("INSERT INTO people(person_id,name,department,created_at,updated_at) VALUES(?,?,?,?,?)",
                               (person_id, name, department, stamp, stamp))
            for filename, embedding in encoded:
                conn.execute("INSERT INTO face_samples(person_id,filename,embedding,created_at) VALUES(?,?,?,?)",
                             (cur.lastrowid, filename, json.dumps(embedding), stamp))
        return jsonify(message="Person added", id=cur.lastrowid), 201
    except sqlite3.IntegrityError:
        return jsonify(error="That ID/roll number is already registered."), 409
    except (ValueError, RuntimeError) as exc:
        return jsonify(error=str(exc)), 400


@app.put("/api/people/<int:person_db_id>")
def update_person(person_db_id: int):
    payload = request.get_json(silent=True) or {}
    try:
        name = valid_text(payload.get("name"), "Name")
        person_id = valid_text(payload.get("person_id"), "ID/roll number")
        department = (payload.get("department") or "").strip()[:100]
        with db() as conn:
            conn.execute("UPDATE people SET name=?,person_id=?,department=?,updated_at=? WHERE id=?",
                         (name, person_id, department, now_iso(), person_db_id))
        return jsonify(message="Person updated")
    except sqlite3.IntegrityError:
        return jsonify(error="That ID/roll number is already registered."), 409
    except ValueError as exc:
        return jsonify(error=str(exc)), 400


@app.delete("/api/people/<int:person_db_id>")
def delete_person(person_db_id: int):
    with db() as conn:
        row = conn.execute("SELECT id FROM people WHERE id=?", (person_db_id,)).fetchone()
        if not row:
            return jsonify(error="Person not found."), 404
        conn.execute("DELETE FROM people WHERE id=?", (person_db_id,))
    return jsonify(message="Person deleted")


@app.post("/api/recognize")
def recognize_api():
    file = request.files.get("image")
    if not file or not file.filename:
        return jsonify(error="An image file is required."), 400
    if Path(file.filename).suffix.lower().lstrip(".") not in ALLOWED_EXTENSIONS:
        return jsonify(error="Only JPG, JPEG, PNG, and WEBP images are allowed."), 400
    try:
        results = recognize(image_from_bytes(file.read()))
        source = request.form.get("source", "camera")
        marked = []
        for result in results:
            if result["recognized"]:
                match = result["match"]
                result["attendance_marked"] = maybe_mark(match["person_db_id"], match["confidence"], source)
                marked.append(match["name"])
        return jsonify(faces=results, marked=marked, processed_at=now_iso())
    except (ValueError, RuntimeError) as exc:
        return jsonify(error=str(exc)), 400


@app.get("/api/attendance")
def attendance():
    search = (request.args.get("search") or "").strip()
    date = (request.args.get("date") or "").strip()
    query = """SELECT a.id,p.person_id,p.name,p.department,a.attendance_date,a.marked_at,
               a.confidence,a.status,a.source FROM attendance a JOIN people p ON p.id=a.person_id
               WHERE 1=1"""
    params: list[str] = []
    if search:
        query += " AND (p.name LIKE ? OR p.person_id LIKE ?)"
        params.extend([f"%{search}%", f"%{search}%"])
    if date:
        query += " AND a.attendance_date=?"
        params.append(date)
    query += " ORDER BY a.id DESC LIMIT 500"
    with db() as conn:
        rows = conn.execute(query, params).fetchall()
    return jsonify([json_row(row) for row in rows])


init_db()
seed_existing_faces()

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=False)

